{
  "technical_and_design_decisions": [
    "ZooKeeper namespace isolation will be implemented by making the Curator / ZooKeeper client root path configurable via tenant environment profiles.",
    "Interactive CLI authentication for xd-shell will use Console readPassword prompt to capture credentials in-memory without persisting or logging passwords to disk.",
    "Dynamic port discovery for xd-shell will register Admin Server's randomly allocated Spring Boot / Tomcat HTTP port into ZooKeeper under a well-defined ephemeral path.",
    "Kafka consumer upgrade will target the Kafka 0.9+ new Java consumer API, updating spring-integration-kafka message bus adapters and fixing consumer group management tests.",
    "Motion-JPEG spike will focus on pure Java / platform-independent byte-stream parsing to avoid platform-native OpenCV dependency issues in core stream ingestion."
  ],
  "assumptions": [
    "A single senior software developer will execute all implementation, spikes, testing, and deployment activities.",
    "Existing CI/CD infrastructure supports git maintenance branch builds (e.g., 1.0.x) with minimal configuration changes.",
    "Motion-JPEG spike scope is restricted to research, design specifications, and proof-of-concept prototyping rather than a full production-grade video processing pipeline.",
    "All unit and integration tests for modified components will be updated or created as part of their respective activities."
  ],
  "activities": [
    {
      "activity_id": "ACT-1",
      "activity_name": "Tenant-based ZooKeeper Namespace Configuration (U1)",
      "activity_description": "Implement configurable ZooKeeper root namespaces driven by active tenant profiles to ensure isolation of metadata per tenant.",
      "most_likely_effort": 2.5
    },
    {
      "activity_id": "ACT-2",
      "activity_name": "Interactive CLI Authentication for Admin Server (U2)",
      "activity_description": "Enhance xd-shell to prompt users interactively for username and password credentials, preventing credentials from being saved in configuration files or logs.",
      "most_likely_effort": 2.0
    },
    {
      "activity_id": "ACT-3",
      "activity_name": "Maintenance Branch and CI Pipeline Setup (U3)",
      "activity_description": "Create minor release maintenance branch (e.g., 1.0.x) and configure build scripts and CI pipelines for isolated release management.",
      "most_likely_effort": 1.0
    },
    {
      "activity_id": "ACT-4",
      "activity_name": "Deprecated Module Registry and UI Cleanup (U4)",
      "activity_description": "Remove deprecated module registry functions (such as module definition downloads) and clean up corresponding unused code in xd-shell and Admin-UI modules.",
      "most_likely_effort": 2.5
    },
    {
      "activity_id": "ACT-5",
      "activity_name": "Dynamic Admin Server Port Discovery Spike & Implementation (U5)",
      "activity_description": "Perform spike research on xd-shell to Admin Server connectivity via ZooKeeper vs. Load Balancer, and implement ZK-based dynamic Tomcat port lookup.",
      "most_likely_effort": 3.5
    },
    {
      "activity_id": "ACT-6",
      "activity_name": "Kafka Consumer Rewrite Upgrade and Test Fixes (U6)",
      "activity_description": "Upgrade Kafka message bus components to the new Kafka consumer client rewrite and resolve previously failing integration tests.",
      "most_likely_effort": 3.0
    },
    {
      "activity_id": "ACT-7",
      "activity_name": "Motion-JPEG Streaming Ingestion Spike & Design Spec (U7)",
      "activity_description": "Conduct research spike on Motion-JPEG audio/video stream ingestion feasibility, evaluate platform-independent image processing options, and author technical design spec.",
      "most_likely_effort": 4.0
    },
    {
      "activity_id": "ACT-8",
      "activity_name": "Cluster View Message Rates Config Toggle (U8)",
      "activity_description": "Add configurable parameter in servers.yml to enable or disable message rate calculations and metrics rendering in the cluster view UI/API.",
      "most_likely_effort": 1.5
    },
    {
      "activity_id": "ACT-9",
      "activity_name": "End-to-End Integration Testing and Regression Verification",
      "activity_description": "Execute full integration test suite across modified modules (xd-shell, Admin Server, ZK, Kafka bus) to ensure increment stability.",
      "most_likely_effort": 2.0
    }
  ],
  "reported_total": {
    "most_likely_effort": 22.0
  }
}
